async function readOptionalSecret(name: string): Promise<string> {
  try {
    return String((await secrets.readSecret(name)) || '').trim();
  } catch {
    return '';
  }
}

// Der eBay-Provider hält sein OAuth-Token (ca. 2 h gültig) im Speicher. Solange der Container warm
// ist, wird er wiederverwendet statt pro Anfrage ein neues Token zu holen.
let ebayProviderCache: { key: string; provider: StructuredMarketProvider } | null = null;

/**
 * Kostenlose strukturierte Quellen aus den App-Secrets (EBAY_CLIENT_ID + EBAY_CLIENT_SECRET,
 * SERPAPI_API_KEY). Fehlt ein Secret, wird die jeweilige Quelle nicht verwendet und die Marktsuche
 * läuft wie bisher. Schlüssel werden nie geloggt oder an das Frontend gegeben.
 */
async function freeMarketProviders(lensImage: LensImage | null): Promise<StructuredMarketProvider[]> {
  const [ebayClientId, ebayClientSecret, serpApiKey] = await Promise.all([
    readOptionalSecret('EBAY_CLIENT_ID'),
    readOptionalSecret('EBAY_CLIENT_SECRET'),
    readOptionalSecret('SERPAPI_API_KEY'),
  ]);
  const providers: StructuredMarketProvider[] = [];
  if (ebayClientId && ebayClientSecret) {
    const key = ebayClientId + '\n' + ebayClientSecret;
    if (!ebayProviderCache || ebayProviderCache.key !== key) {
      ebayProviderCache = {
        key,
        provider: createEbayBrowseProvider({ clientId: ebayClientId, clientSecret: ebayClientSecret }),
      };
    }
    providers.push(ebayProviderCache.provider);
  }
  if (serpApiKey && lensImage) {
    providers.push(createGoogleLensProvider({ apiKey: serpApiKey, image: lensImage, timeoutMs: 8000 }));
  }
  return providers;
}

