// Kleine Kopie des Hauptfotos für die Bildsuche (Google Lens, max. 500 KB). Klappt das Verkleinern
// nicht, läuft die Marktsuche einfach ohne Bildsuche.
async function lensImageFor(file: File | null) {
  if (!file) return null;
  try {
    const prepared = await aiImage.resizeIfNeeded(file, {
      maxDimension: 640,
      maxPixels: 410000,
      quality: 0.7,
      mimeType: 'image/jpeg',
    });
    return { data: prepared.data, mimeType: prepared.mimeType };
  } catch {
    return null;
  }
}

